    /// Returns the configuration name from the attribute, falling back to <paramref name="name"/>.
    /// Returns <c>null</c> when <paramref name="attribute"/> is <c>null</c> (member is not configurable).
    /// </summary>
    protected static string? GetConfigurableName(string? name, ConfigurableAttribute? attribute)
    {
        if (attribute == null) return null;
        if (!string.IsNullOrEmpty(attribute.Name)) return attribute.Name;
        return name;
    }

    /// <summary>
    /// Converts <paramref name="configValue"/> to <paramref name="targetType"/> and passes
    /// the result to <paramref name="setter"/>. Tries <see cref="Convert.ChangeType(object, Type, IFormatProvider)"/>
    /// first, then falls back to a public constructor accepting a single <see cref="string"/>.
    /// </summary>
    /// <returns><c>true</c> if conversion and setting succeeded; otherwise <c>false</c>.</returns>
    protected bool TryConvertAndSet(string configValue, Type targetType, Action<object?> setter)
    {
        try
        {
            // Attempt simple type conversion (e.g., int, bool, DateTime, etc.)
            // Use InvariantCulture for culture-neutral conversion
            object? convertedValue = Convert.ChangeType(configValue, targetType, CultureInfo.InvariantCulture);
            setter(convertedValue);
            return true;
        }
        catch
        {
            // If simple conversion fails, try to use a constructor that accepts a single string
            try
            {
                var constructor = targetType.GetConstructor(new[] { typeof(string) });
                if (constructor != null)
                {
                    object? instance = constructor.Invoke(new object[] { configValue });
                    setter(instance);
                    return true;
                }
            }
            catch
            {
                // silently ignore conversion errors and leave the field unchanged
            }
        }
        return false;
    }

    /// <summary>The assembly that contains this configurable member.</summary>
    public required Assembly Assembly { get; init; }

    /// <summary>The type that declares this configurable member.</summary>
    public required Type DeclaringClassType { get; init; }

    /// <summary>The simple name of the underlying field or property.</summary>
    public abstract string FieldName { get; }

    /// <summary>The CLR type of the underlying field or property.</summary>
    public abstract Type FieldType { get; }

    /// <summary>The <see cref="ConfigurableAttribute"/> applied at the assembly level.</summary>
    public ConfigurableAttribute AssemblyAttribute => Assembly.GetCustomAttribute<ConfigurableAttribute>()!;

    /// <summary>The <see cref="ConfigurableAttribute"/> applied at the type level.</summary>
    public ConfigurableAttribute DeclaringClassTypeAttribute => DeclaringClassType.GetCustomAttribute<ConfigurableAttribute>()!;

    /// <summary>The <see cref="ConfigurableAttribute"/> applied to this field or property.</summary>
    public abstract ConfigurableAttribute FieldAttribute { get; }

    /// <summary>Reads the current value of the member from <paramref name="instance"/> (pass <c>null</c> for static members).</summary>
    public abstract object? GetValue(object? instance);

    /// <summary>Writes <paramref name="value"/> to the member on <paramref name="instance"/> (pass <c>null</c> for static members).</summary>
    public abstract void SetValue(object? instance, object? value);
    /// <summary>
    /// Try to set field (with optional instance) to value. 
    /// </summary>
    /// <param name="instance">
    /// The target instance, or <c>null</c> for static member binding.
    /// When <c>null</c>, only static members are set.
    /// When non-null, only instance members are set.
    /// </param>
    /// <param name="configValue">The configuration string to convert and assign.</param>
    /// <returns>
    /// <c>false</c> if the member/instance combination is mismatched (instance member
    /// without an instance, or static member with an instance) or if the value cannot
    /// be converted. <c>true</c> otherwise.
    /// </returns>
    public virtual bool TrySetValue(object? instance, string configValue)
    {
        if (instance == null && !IsStatic) return false;
        if (instance != null && IsStatic) return false;
        return TryConvertAndSet(configValue, FieldType, value => SetValue(instance, value));
    }
    /// <summary>Indicates whether the underlying member is static.</summary>
    public abstract bool IsStatic { get; }

    /// <summary>
    /// Gets the fully qualified configuration path for this member, constructed as
    /// <c>[AssemblyName]:[TypeName]:[MemberName]</c>.
    /// The assembly prefix is omitted when the assembly-level attribute name is empty.
    /// </summary>
    public virtual string Path
    {
        get
        {
            var an = GetConfigurableName(string.Empty, AssemblyAttribute);
            if (an != string.Empty) an += ":";
            return $"{an}{GetConfigurableName(DeclaringClassType.Name, DeclaringClassTypeAttribute)}:{GetConfigurableName(FieldName, FieldAttribute)}";
        }
    }

    /// <summary>
    /// Returns the current value formatted as an invariant-culture string.
    /// Useful for round-trip comparison with configuration values.
    /// </summary>
    /// <param name="instance">The object instance, or <c>null</c> for static members.</param>
    public virtual string? IdempotentStringValue(Object? instance) => Convert.ToString(GetValue(instance), CultureInfo.InvariantCulture);
}
/// <summary>
/// <see cref="ConfigurableItem"/> implementation backed by a <see cref="FieldInfo"/>.
/// </summary>
internal class ConfigurableField : ConfigurableItem
{
    /// <summary>The reflected field this item wraps.</summary>
    public required FieldInfo Field { get; init; }
    public override Type FieldType => Field.FieldType;
    public override string FieldName => Field.Name;
    public override ConfigurableAttribute FieldAttribute => Field.GetCustomAttribute<ConfigurableAttribute>()!;
    public override object? GetValue(object? instance)
    {
        return Field.GetValue(instance);
    }
    public override void SetValue(object? instance, object? value)
    {
        Field.SetValue(instance, value);
    }
    public override bool IsStatic => Field.IsStatic;
}

